"""Local Ingress dashboard: typed observations, honest gaps, escaped names."""
PAGE=r'''<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Energetický koordinátor</title><style>
:root{color-scheme:dark;font-family:system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:#101821;color:#edf2f7}main{max-width:1400px;margin:auto;padding:24px}h1{font-size:1.65rem;margin:0}h2{font-size:1.12rem;margin:0 0 14px}small,.muted{color:#aebed0;line-height:1.5}.top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.pill{padding:7px 12px;border:1px solid #486279;border-radius:24px;font-size:.8rem}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:14px;margin:16px 0}.card{border:1px solid #334759;background:#192633;border-radius:12px;padding:18px;margin:14px 0}.grid .card{margin:0}.big{font-size:1.7rem;font-weight:650;margin:8px 0}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:.85rem}th,td{padding:9px;text-align:left;border-bottom:1px solid #334759;vertical-align:top}th{color:#add5ea}canvas{width:100%;height:265px;display:block}select,input{background:#101821;color:#fff;border:1px solid #55748d;padding:8px;border-radius:6px;max-width:100%}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:10px}nav{display:flex;gap:16px;flex-wrap:wrap;margin:20px 0}a{color:#8bd5ff}.legend{display:flex;gap:14px;flex-wrap:wrap;font-size:.8rem;margin:10px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.8rem}.error{color:#ffadad}details{margin-top:14px}@media(max-width:640px){main{padding:12px}.card{padding:14px}.grid{grid-template-columns:1fr}h1{font-size:1.2rem}.pill{white-space:nowrap}canvas{height:235px}}
</style></head><body><main><div class="top"><div><h1>Energetický koordinátor 0.5</h1><small>Počasí · teplotní zóny · energie · kvalita dat</small></div><span class="pill">RPi4 · pozorování</span></div><p id="error" class="error" role="status"></p>
<nav><a href="#shadow">Stínový plán</a><a href="#weather">Počasí</a><a href="#temperatures">Teploty</a><a href="#pv">FVE</a><a href="#ev">Auto</a><a href="#appliances">Spotřebiče</a><a href="#catalog">Čidla</a></nav>
<div class="grid"><div class="card"><small>SBĚR DAT</small><div id="samples" class="big">—</div><small id="health"></small></div><div class="card"><small>ŠIRŠÍ TELEMETRIE</small><div id="count" class="big">—</div><small id="quality"></small></div><div class="card"><small>FVE ZÍTRA · MODEL</small><div id="forecast" class="big">—</div><small id="forecast-note"></small></div><div class="card"><small>EV · TARIFNÍ EKVIVALENT</small><div id="ev-total" class="big">—</div><small id="ev-note"></small></div></div><p id="calendar" class="muted"></p>
<section id="shadow" class="card"><h2>Dům: skutečnost a stínový scénář nabíjení</h2><p id="shadow-status" class="muted"></p><p id="shadow-week" class="muted"></p><canvas id="shadow-chart"></canvas><div id="shadow-legend" class="legend"></div><div id="shadow-table" class="scroll"></div><p class="muted">Plná čára skutečnosti je měření, návrh je model budoucího domu bez změny ostatních zátěží. Scénář předpokládá, že auto zůstane připojené do zadaného času. Nezahrnuje řízení baterie, prodej přebytků ani změny vytápění. Nepředstavuje prokázanou úsporu a nic nespíná.</p></section>
<section id="weather" class="card"><h2>Počasí: předpověď versus místní měření</h2><select id="weather-select" aria-label="Zdroj a předstih"></select><canvas id="weather-chart"></canvas><div id="weather-legend" class="legend"></div><p id="weather-note" class="muted"></p><div id="weather-table" class="scroll"></div><details><summary>Poslední načtení předpovědí</summary><pre id="weather-attempts"></pre></details></section>
<section id="temperatures" class="card"><h2>Teploty jednotlivých čidel</h2><select id="temperature-select" aria-label="Čidlo teploty"></select><canvas id="temperature-chart"></canvas><div id="temperature-legend" class="legend"></div><small>Čidla místností, vody a elektroniky neslučujeme. Zobrazeno 24 hodin hlášení; výpadky nejsou nuly.</small></section>
<div class="grid"><section id="pv" class="card"><h2>Solcast a následná výroba</h2><canvas id="pv-chart"></canvas><div id="pv-legend" class="legend"></div><small>Korekce v tomto historickém grafu je test na pozdějších dnech, nikoli dříve vydaná predikce. Vydané odhady se archivují samostatně.</small><div id="pv-models" class="scroll"></div></section><section class="card"><h2>Samokalibrace spotřeby</h2><p id="calibration"></p><h2>Domácí baterie</h2><p id="battery"></p><small>Poměr energie ke změně SOC sám neprokazuje degradaci. Katalogové údaje nejsou aktuálně změřená kapacita.</small></section></div>
<section id="ev" class="card"><h2>Auto: měsíční energie a náklady</h2><div id="ev-months" class="scroll"></div><h2 style="margin-top:22px">Nabíjecí relace</h2><div id="ev-sessions" class="scroll"></div><p class="muted">Tarifní ekvivalent = dodaná energie oceněná nákupním tarifem. Není to faktura ani důkaz původu elektřiny ze sítě. Uvnitř měřicího intervalu se energie rozděluje časově; neoceněné kWh zůstávají označené.</p></section>
<section id="appliances" class="card"><h2>Spotřebiče a cykly</h2><div id="appliance-table" class="scroll"></div><small>Trend vyžaduje dvě pokrytá týdenní období. Cykly/den používají pouze úplné dny; krátká historie není doplněna nulami.</small></section>
<section class="card"><h2>Denní energie</h2><canvas id="daily-chart"></canvas><div id="daily-legend" class="legend"></div><small>Denní čítače od nasazení této verze; první den a výpadky mohou být neúplné. Původní historie zůstává v archivu.</small></section>
<section id="catalog" class="card"><h2>Katalog čidel a kvalita</h2><div class="toolbar"><input id="filter" placeholder="Název, ID, oblast…" aria-label="Filtr čidel"><select id="type-filter" aria-label="Typ čidla"></select></div><p id="catalog-note" class="muted"></p><div id="catalog-table" class="scroll"></div><details><summary>Slunce a astronomické údaje</summary><pre id="sun"></pre></details></section><p class="muted">Pouze HA/RPi4. Žádné ovládání spotřebičů ani automatické odesílání do AI. Neověřené role archivujeme, ale nepoužíváme je automaticky pro řízení.</p></main>
<script>
let data={},status={},cal={};const colors=['#71cceb','#e8bb6e','#7ad7b6','#d3a4ed'];
const tr=v=>({autumn:'podzim',winter:'zima',summer:'léto',spring:'jaro',collecting:'sbírá podklady',collecting_pairs:'sbírá dvojice předpověď/měření',ok:'v pořádku',unknown:'neznámé'})[v]||v||'—';
const el=id=>document.getElementById(id),txt=(id,v)=>{el(id).textContent=v};
const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,d=2)=>v==null||!Number.isFinite(Number(v))?'—':Number(v).toLocaleString('cs-CZ',{maximumFractionDigits:d});
const stamp=v=>v?new Date(v).toLocaleString('cs-CZ',{timeZone:'Europe/Prague',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
function table(id,headers,rows){el(id).innerHTML=rows.length?'<table><thead><tr>'+headers.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>':'<p class="muted">Zatím není dostatek dat.</p>'}
function options(id,rows){const s=el(id),old=s.value;s.replaceChildren();for(const [v,t] of rows){const o=document.createElement('option');o.value=v;o.textContent=t;s.append(o)}if(rows.some(r=>r[0]===old))s.value=old}
function graph(id,legend,rows,series,unit){const canvas=el(id),ctx=canvas.getContext('2d'),w=Math.max(300,canvas.clientWidth),h=canvas.clientHeight,dpr=window.devicePixelRatio||1;canvas.width=w*dpr;canvas.height=h*dpr;ctx.scale(dpr,dpr);ctx.font='12px system-ui';el(legend).replaceChildren();series.forEach(([key,name],i)=>{let b=document.createElement('span');b.style.color=colors[i%4];b.textContent=name;el(legend).append(b)});let pts=rows.map(r=>({...r,t:Date.parse(r.at||r.target||r.date)})).filter(r=>Number.isFinite(r.t)),values=pts.flatMap(r=>series.map(([k])=>r[k]).filter(v=>typeof v==='number'&&Number.isFinite(v)));if(!values.length){ctx.fillStyle='#adbacc';ctx.fillText('Zatím není dost měření pro graf.',18,40);return}let lo=Math.min(0,...values),hi=Math.max(...values);if(hi<=lo)hi=lo+1;const x0=Math.min(...pts.map(r=>r.t)),x1=Math.max(...pts.map(r=>r.t)),left=45,top=22,bottom=h-35,width=w-left-16;ctx.strokeStyle='#3f5366';ctx.fillStyle='#adbacc';for(let i=0;i<4;i++){const y=top+(bottom-top)*i/3;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(w-12,y);ctx.stroke();ctx.fillText(n(hi-(hi-lo)*i/3,1),2,y+4)}ctx.fillText(unit,2,13);series.forEach(([key],j)=>{ctx.strokeStyle=colors[j%4];ctx.fillStyle=colors[j%4];ctx.lineWidth=2;ctx.beginPath();let prev=null;for(const p of pts){const v=p[key];if(typeof v!=='number'||!Number.isFinite(v)){prev=null;continue}const x=left+width*(p.t-x0)/Math.max(1,x1-x0),y=bottom-(bottom-top)*(v-lo)/(hi-lo);if(prev===null||p.t-prev>3*3600000)ctx.moveTo(x,y);else ctx.lineTo(x,y);prev=p.t}ctx.stroke();for(const p of pts){if(typeof p[key]!=='number'||!Number.isFinite(p[key]))continue;ctx.beginPath();ctx.arc(left+width*(p.t-x0)/Math.max(1,x1-x0),bottom-(bottom-top)*(p[key]-lo)/(hi-lo),2,0,2*Math.PI);ctx.fill()}});ctx.fillStyle='#adbacc';const fmt=t=>new Date(t).toLocaleString('cs-CZ',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Prague'});ctx.fillText(fmt(x0),left,h-10);ctx.textAlign='right';ctx.fillText(fmt(x1),w-10,h-10);ctx.textAlign='left'}
function draw(){let choice=el('weather-select').value;graph('weather-chart','weather-legend',(data.weather?.pairs||[]).filter(r=>r.provider+'|'+r.bucket===choice),[['forecast_c','Předpověď'],['actual_c','Místní čidlo']],'°C');let eid=el('temperature-select').value;graph('temperature-chart','temperature-legend',data.environment?.temperature_series?.[eid]||[],[['value',eid||'Čidlo']],'°C');graph('daily-chart','daily-legend',data.daily||[],[['pv_kwh','FVE'],['house_kwh','Dům'],['import_kwh','Import'],['export_kwh','Export']],'kWh');graph('pv-chart','pv-legend',(data.pv?.recent_pairs||[]).filter(r=>r.bucket==='6-24h'),[['raw_kwh','Raw'],['corrected_kwh','Holdout korekce'],['actual_kwh','Výroba']],'kWh');graph('shadow-chart','shadow-legend',[...(data.shadow?.actual||[]),...(data.shadow?.candidate?.slots||[])],[['house_kw','Naměřený dům'],['planned_house_kw','Scénář domu']],'kW')}
function catalog(){const q=el('filter').value.toLowerCase(),kind=el('type-filter').value;const rows=(data.environment?.points||[]).filter(p=>(!kind||p.quantity===kind)&&JSON.stringify([p.entity_id,p.label,p.area_name,p.zone,p.role]).toLowerCase().includes(q));txt('catalog-note',rows.length+' čidel; nedostupná hodnota není nula.');table('catalog-table',['Čidlo / ID','Oblast / role','Typ','Hodnota','Kvalita','Stáří hlášení'],rows.map(p=>[p.label+' · '+p.entity_id,(p.zone||p.area_name||'nepřiřazeno')+' / '+p.role,p.quantity,(p.value??'—')+' '+(p.unit||''),p.quality,p.report_age_seconds==null?'—':n(p.report_age_seconds/60,1)+' min']))}
function shadowView(){const s=data.shadow||{},p=s.candidate||{};const labels={needs_configuration:'Chybí ověřené parametry auta v nastavení aplikace.',invalid_deadline:'Zadaný čas připravenosti není platný.',collecting:'Sbíráme data.',stale_measurements:'Poslední měření není dost čerstvé.',car_not_confirmed_connected:'Auto není připojené; plán začne po připojení.',stale_connection:'Připojení auta není potvrzené čerstvým údajem.',missing_soc_or_target:'Chybí aktuální nabití nebo cíl auta.',target_met:'Cílové nabití je již dosažené.',collecting_house_profile:'Sbíráme pokryté hodiny spotřeby domu bez auta.',missing_forecast_profile_or_tariff:'Chybí profil domu, předpověď FVE nebo archivovaný tarif pro část období.',insufficient_window:'Do požadovaného času není dost prostoru pro potřebné nabití.'};txt('shadow-status',p.status==='scenario'?'Stínový návrh z '+stamp(p.issued_at)+' · požadavek '+n(p.needed_ac_kwh)+' kWh do '+stamp(p.ready_by)+'. Odhad, bez vykonaných akcí.':labels[p.status]||'Návrh zatím není k dispozici.');const w=s.weekly_review||{};txt('shadow-week',w.status==='descriptive'?'Minulý týden: '+n(w.scenarios,0)+' uložených návrhů, '+n(w.covered_slots,0)+' čtvrthodin s měřením, odchylka scénáře od reality '+n(w.mean_absolute_house_difference_kw,2)+' kW. Nejde o prokázanou úsporu.':'Týdenní kontrola: zatím chybí dost společných návrhů a měření.');table('shadow-table',['Čas','Auto kW','FVE odhad kW','Dům odhad kW','Nákup Kč/kWh'],(p.slots||[]).filter(x=>x.planned_ev_kw>0).map(x=>[stamp(x.at),n(x.planned_ev_kw),n(x.pv_forecast_kw),n(x.planned_house_kw),n(x.buy_price)]))}
function render(){const env=data.environment||{},q=env.quality||{},up=data.pv?.upcoming?.tomorrow,e=data.ev?.month||{},w=data.weather||{},b=data.battery||{},c=env.calendar||{};txt('samples',n(status.samples,0)+' vzorků');txt('health','Poslední sběr '+stamp(status.last_observed_at));txt('count',n(q.count,0)+' čidel');txt('quality',n(q.valid,0)+' dostupných · '+n(q.unclassified_temperatures,0)+' nepřiřazených teplot');txt('forecast',n(up?.corrected_kwh)+' kWh');txt('forecast-note','Raw '+n(up?.raw_kwh)+' kWh · '+tr(data.pv?.status));txt('ev-total',n(e.home_charge_kwh)+' kWh · '+n(e.tariff_equivalent_cost_czk)+' Kč');txt('ev-note','Neoceněno '+n(e.unpriced_kwh)+' kWh');txt('calendar','Profil '+tr(c.season)+' · tarifní sezóna '+tr(c.tariff_season)+' · pracovní den '+(c.workday==null?'neznámý':c.workday?'ano':'ne')+' · '+(c.local_date||'—'));options('weather-select',[...new Set((w.pairs||[]).map(r=>r.provider+'|'+r.bucket))].map(k=>[k,k]));options('temperature-select',(env.points||[]).filter(p=>p.quantity==='temperature').map(p=>[p.entity_id,(p.zone||p.area_name||'nezařazeno')+' — '+p.label]));options('type-filter',[['','Všechny typy'],...Object.keys(env.counts_by_quantity||{}).sort().map(k=>[k,k])]);txt('weather-note','Reference '+(w.reference_entity||'—')+' · '+tr(w.status)+' · hodnotíme hodinovou teplotu, ne denní maximum.');txt('weather-attempts',JSON.stringify(w.attempts||[],null,2));table('weather-table',['Zdroj','Předstih','Páry','MAE °C','Odchylka °C'],(w.metrics||[]).map(m=>[m.provider,m.lead_bucket,m.n,n(m.mae_c),n(m.bias_c)]));table('pv-models',['Profil','Trénink dnů','Test dnů','MAE raw','MAE kor.'],Object.entries(data.pv?.models||{}).map(([k,m])=>[k,m.train_days,m.test_days,n(m.mae_raw_kwh,3),n(m.mae_corrected_kwh,3)]));txt('calibration',tr(cal.status)+' · celé dny '+(cal.complete_days??0)+' / '+(cal.minimum_complete_days??14)+' · chyba '+n(cal.validation?.reference_mae_w)+' → '+n(cal.validation?.candidate_mae_w)+' W');txt('battery','Katalog '+n(b.spec?.nominal_kwh)+' / '+n(b.spec?.usable_kwh)+' kWh. Pozorovaný poměr energie/SOC '+n(b.observed_energy_per_soc100_kwh)+'. SoH neověřeno.');table('ev-months',['Měsíc','kWh','Tarifní Kč','Kč/kWh','Neoceněné kWh'],(data.ev?.months||[]).map(m=>[m.month,n(m.home_charge_kwh,3),n(m.tariff_equivalent_cost_czk),n(m.weighted_price_czk_kwh,3),n(m.unpriced_kwh,3)]));table('ev-sessions',['Začátek','kWh','Kč','Stav'],(data.ev?.sessions||[]).slice().reverse().map(s=>[stamp(s.start),n(s.energy_kwh),n(s.tariff_equivalent_cost_czk),s.status]));table('appliance-table',['Spotřebič','Typ','7 dní kWh','30 dní Kč','Celých dní','Cykly/den','kWh/cyklus','Trend'],Object.values(data.appliances||{}).map(a=>[a.label,a.kind,n(a.energy_7d_kwh),n(a.tariff_equivalent_cost_30d_czk),a.complete_days_30d,n(a.cycles_per_day_30d),n(a.avg_cycle_kwh),a.trend_7d_vs_prev7_pct==null?'málo dat':n(a.trend_7d_vs_prev7_pct)+' %']));txt('sun',JSON.stringify((env.points||[]).filter(p=>p.quantity==='sun'),null,2));catalog();shadowView();draw()}
async function load(){try{const values=await Promise.all(['status.json','analytics.json','calibration.json'].map(async u=>{const r=await fetch(u,{cache:'no-store'});if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}));[status,data,cal]=values;txt('error','');render();if(status.last_observed_at&&Date.now()-Date.parse(status.last_observed_at)>180000)txt('error','Sběr nemá čerstvá data. Zobrazené hodnoty mohou být zastaralé.')}catch(e){txt('error','Načtení selhalo; poslední hodnoty nejsou nové měření.')}}
el('weather-select').onchange=draw;el('temperature-select').onchange=draw;el('filter').oninput=catalog;el('type-filter').onchange=catalog;window.addEventListener('resize',draw);load();setInterval(load,60000);
</script></body></html>'''
